SELECT t.* FROM `transaction` t
WHERE t.wallet_id = #{walletId}

    AND t.txn_type IN ('DEPOSIT', 'REFUND')


    AND t.txn_type IN ('PAYMENT', 'WITHDRAW', 'TRANSFER')
    AND NOT EXISTS (
        SELECT 1 FROM group_purchase_participant gpp
        WHERE gpp.txn_id = t.txn_id AND gpp.payment_status = 'CANCELLED'
    )


    AND t.txn_type = 'PAYMENT'
    AND NOT EXISTS (
        SELECT 1 FROM group_purchase_participant gpp
        WHERE gpp.txn_id = t.txn_id AND gpp.payment_status = 'CANCELLED'
    )

AND t.txn_date >= #{startDate}
AND t.txn_date < #{endDate}

    AND (t.txn_date < #{cursorDate}
         OR (t.txn_date = #{cursorDate} AND t.txn_id < #{cursorTxnId}))

ORDER BY t.txn_date DESC, t.txn_id DESC
LIMIT #{limit}

SELECT t.* FROM `transaction` t
WHERE t.wallet_id = #{walletId}

    AND t.txn_type IN ('DEPOSIT', 'REFUND')


    AND t.txn_type IN ('PAYMENT', 'WITHDRAW', 'TRANSFER')
    AND NOT EXISTS (
        SELECT 1 FROM group_purchase_participant gpp
        WHERE gpp.txn_id = t.txn_id AND gpp.payment_status = 'CANCELLED'
    )

ORDER BY t.txn_date DESC, t.txn_id DESC
LIMIT #{limit}

